import React, { Component } from 'react';
import { Card } from 'reactstrap';
import QrReader from 'react-qr-reader';

class QRCodeReader extends Component {

    constructor(props){
        super(props);

        this.state = {
            result: 'No result',
            copied: false
        };
    }

    handleScan = (data) => {
        console.log(data);
        if (data) {
            this.setState({ result: data, copied: false });
        }
    }

    copyToClipboard = () => {
        navigator.clipboard.writeText(this.state.result).then(() => {
            this.setState({ copied: true });
            setTimeout(() => this.setState({ copied: false }), 2000);
        }).catch(err => {
            console.error("Failed to copy to clipboard:", err);
        });
    }

    handleError = (err) => {
        console.error("handleError() : err :" , err);
    }

    render() {
        return (
            <Card>
                Hello from QRCodeReader ~~~~ !!!!

                RESULT :
                <hr/>
                <h1>{this.state.result}</h1>
                <button
                    onClick={this.copyToClipboard}
                    disabled={this.state.result === 'No result'}
                    style={{ marginTop: '8px', padding: '6px 16px', cursor: 'pointer' }}
                >
                    {this.state.copied ? '✓ Copied' : 'Copy'}
                </button>
                <button
                    onClick={() => this.setState({ result: 'No result', copied: false })}
                    disabled={this.state.result === 'No result'}
                    style={{ marginTop: '8px', marginLeft: '8px', padding: '6px 16px', cursor: 'pointer' }}
                >
                    Clear
                </button>
                <hr/>
                
                <br /><br />

                <QrReader
                    delay={100}
                    onError={this.handleError}
                    onScan={this.handleScan}
                    style={{ width: '70%' , height: "70%"}}
                />
        

            </Card>
        )
    }

}

export default QRCodeReader;